					}
					data, ok := mm["data"].(map[string]any)
					if !ok {
						continue
					}
					text, _ := data["text"].(string)
					text = strings.TrimSpace(text)
					// Link and image items both use data.url; only link targets
					// belong alongside the readable label.
					if mm["type"] == "link" {
						url, _ := data["url"].(string)
						url = strings.TrimSpace(url)
						if text == "" {
							text = url
						} else if url != "" && url != text {
							text += "（" + url + "）"
						}
					}
					if text != "" {
						texts = append(texts, text)
					}
				}
			}
			for _, e := range t {
				walk(e)
			}
		}
	}
	walk(node)
	return texts
}

func CleanText(s string) string {
	if IsEncrypted(s) {
		return "[加密消息，无法解码]"
	}

	// Fast path: no JSON delimiters at all — the overwhelming common case.
	if !strings.ContainsAny(s, "{[") {
		return s
	}

	lines := strings.Split(s, "\n")
	isJSON := make([]bool, len(lines))
	isDecoration := make([]bool, len(lines))
	extracted := make([][]string, len(lines))
	anyExtracted := false
	for i, line := range lines {
		t := strings.TrimSpace(line)
		if !strings.HasPrefix(t, "{") && !strings.HasPrefix(t, "[") {
			continue
		}
		var v any
		if json.Unmarshal([]byte(t), &v) != nil {
			continue
		}
		isJSON[i] = true
		isDecoration[i] = isKnownRichDecoration(v)
		if texts := richItemTexts(v); len(texts) > 0 {
			extracted[i] = texts
			anyExtracted = true
		}
	}

	// No recognised rich-content block anywhere → treat the whole body as plain
	// text (which may merely contain a JSON fragment) and return it untouched.
	if !anyExtracted {
		return s
	}

	out := make([]string, 0, len(lines))
	for i, line := range lines {
		if len(extracted[i]) > 0 {
			out = append(out, extracted[i]...)
			continue
		}
		// In card mode, drop only JSON shapes known to be card decoration.
		// Unrecognised JSON may be user-authored message content and must remain
		// verbatim even when another line contains a rich-content block.
		if isJSON[i] && isDecoration[i] {
			continue
		}
		if t := strings.TrimSpace(line); t == "" || t == "empty" {
			continue
		}
		out = append(out, line)
	}
	// anyExtracted is true here, so out always holds at least one non-empty
	// extracted text — the joined result is never empty.
	return strings.TrimSpace(strings.Join(out, "\n"))
}

func DecryptChatMessageItems(ctx context.Context, rt messagecrypto.Runtime, items []map[string]any) map[string]any {
	if ctx == nil || rt == nil || rt.DryRun() ||
		messageDecryptClient == nil || messageDecryptClient.BackendReady == nil || !messageDecryptClient.BackendReady() {
		return nil
	}
	batchItems := make([]messagecrypto.BatchDecryptItem, 0)
	targets := map[decryptItemKey][]decryptTarget{}
	for _, item := range items {
		messageID := strings.TrimSpace(fmt.Sprint(MessageID(item)))
		if messageID == "" || messageID == "<nil>" {
			continue
		}
		contentKey, ciphertext := encryptedItemContent(item)
		if contentKey == "" {
			continue
		}
		conversationID := strings.TrimSpace(fmt.Sprint(ConversationID(item)))
		if conversationID == "<nil>" {
			conversationID = ""
		}
		key := newDecryptItemKey(messageID, conversationID)
		targets[key] = append(targets[key], decryptTarget{message: item, contentKey: contentKey})
		batchItems = append(batchItems, messagecrypto.BatchDecryptItem{
			MessageID:      messageID,
			ConversationID: conversationID,
			Ciphertext:     ciphertext,
		})
	}
	decryptCandidateCount := len(batchItems)
	batchItems, policyFailures := filterDecryptItemsByPolicy(ctx, rt, batchItems)
	ledger := map[string]any{
		"decryptCandidateCount": decryptCandidateCount,
		"decryptAllowedCount":   len(batchItems),
		"decryptedCount":        0,
		"decryptFailedCount":    len(policyFailures),
	}
	if len(policyFailures) > 0 {
		ledger["decryptFailures"] = policyFailures
		ledger["partial"] = true
	}
	if len(batchItems) == 0 {
		return ledger
	}
	result, err := messageDecryptClient.BatchDecryptInbound(ctx, rt, messagecrypto.Options{}, batchItems)
	if err != nil {
		failures := append([]map[string]any{}, policyFailures...)
		failures = append(failures, map[string]any{"stage": "message-decrypt", "reason": err.Error()})
		ledger["decryptFailedCount"] = len(failures)
		ledger["decryptFailures"] = failures
		ledger["partial"] = true
		return ledger
	}
	decryptedCount := 0
	failures := make([]map[string]any, 0)
	for _, item := range result.Items {
		if item.Status != "" && item.Status != "success" {
			failures = append(failures, decryptFailure(item.MessageID, item.ConversationID, item.Reason))
			continue
		}
		if strings.TrimSpace(item.PlaintextContent) == "" {
			failures = append(failures, decryptFailure(item.MessageID, item.ConversationID, "empty_plaintext"))
			continue
		}
		matched := targets[newDecryptItemKey(item.MessageID, item.ConversationID)]
		if len(matched) == 0 {
			continue
		}
		for _, target := range matched {
			target.message[target.contentKey] = item.PlaintextContent
			target.message["contentDecrypted"] = true
			target.message["cryptoLayer"] = "ding+safechat"
			if item.KeyVersion > 0 {
				target.message["dingKeyVersion"] = item.KeyVersion
			}
		}
		decryptedCount++
	}
	for _, item := range result.Failures {
		failures = append(failures, decryptFailure(item.MessageID, item.ConversationID, item.Reason))
	}
	failures = append(policyFailures, failures...)
	ledger["decryptedCount"] = decryptedCount
	ledger["decryptFailedCount"] = len(failures)
	if len(failures) > 0 {
		ledger["decryptFailures"] = failures
		ledger["partial"] = true
	}
	return ledger
}

func employeeBindingAccessPolicy(b digitalEmployeeBinding) string {
	if validMachineString(b.RuntimeBindingID) {
		return "platform"
	}
	return "local_allowlist"
}

func (r *employeeRuntime) accept(e employeeEvent) bool {
	if e.SenderID == r.cfg.SelfOpenDingTalkID {
		return false
	}
	if !validMachineString(e.EventID) || !validMachineString(e.MessageID) || !validMachineString(e.ConversationID) || !validMachineString(e.SenderID) || strings.TrimSpace(e.Content) == "" {
		return false
	}
	if employeeBindingAccessPolicy(r.cfg.Binding) == "platform" {
		switch e.Type {
		case "user_im_message_receive_o2o_all", "user_im_message_receive_o2o", "user_im_message_receive_at":
			return true
		default:
			return false
		}
	}
	if !employeeContains(r.cfg.Options.AllowedUsers, e.SenderID) {
		return false
	}
	switch e.Type {
	case "user_im_message_receive_o2o_all", "user_im_message_receive_o2o":
		return true
	case "user_im_message_receive_group_all", "user_im_message_receive_group", "user_im_message_receive_at":
		return employeeContains(r.cfg.Options.AllowedGroups, e.ConversationID)
	default:
		return false
	}
}

func (s *PersonalSource) runAttempt(ctx context.Context, emit dwsevent.EmitFn) (bool, error) {
	ticket, err := s.fetchTicket(ctx)
	if err != nil {
		return false, err
	}
	wsURL, err := endpointWithTicket(ticket.Endpoint, ticket.Ticket)
	if err != nil {
		return false, err
	}
	conn, _, err := s.cfg.WebSocketDialer.DialContext(ctx, wsURL, nil)
	if err != nil {
		return false, retryPersonal(fmt.Errorf("personal source: dial websocket: %w", err))
	}
	attemptCtx, cancel := context.WithCancel(ctx)
	defer func() {
		cancel()
		_ = conn.Close()
	}()
	closePersonalWebSocketOnContext(attemptCtx, conn)
	s.machine.OnConnected()

	acked := false
	for {
		messageType, data, err := conn.ReadMessage()
		if err != nil {
			if ctx.Err() != nil {
				return acked, ctx.Err()
			}
			return acked, retryPersonal(fmt.Errorf("personal source: read websocket: %w", err))
		}
		if messageType != websocket.TextMessage {
			continue
		}
		if err := s.handleFrame(conn, data, emit); err != nil {
			return acked, err
		}
		acked = true
	}
}

func (s *PersonalSource) handleFrame(conn *websocket.Conn, data []byte, emit dwsevent.EmitFn) error {
	df, err := payload.DecodeDataFrame(data)
	if err != nil {
		return fmt.Errorf("personal source: decode dataframe: %w", err)
	}
	if strings.EqualFold(df.Type, "SYSTEM") {
		resp := payload.NewSuccessDataFrameResponse()
		switch df.GetTopic() {
		case "ping":
			resp = payload.NewDataFrameAckPong(df.GetMessageId())
			resp.Data = df.Data
		case "disconnect":
			// 先确认控制帧，再由重连循环关闭本连接并重新申请 ticket。
		default:
			resp = payload.NewDataFrameResponse(payload.DataFrameResponseStatusCodeKHandlerNotFound)
		}
		resp.SetHeader(payload.DataFrameHeaderKMessageId, df.GetMessageId())
		resp.SetHeader(payload.DataFrameHeaderKContentType, payload.DataFrameContentTypeKJson)
		if err := conn.WriteJSON(resp); err != nil {
			return retryPersonal(fmt.Errorf("personal source: write system ack: %w", err))
		}
		if df.GetTopic() == "disconnect" {
			return retryPersonal(errors.New("personal source: server requested reconnect"))
		}
		return nil
	}
	raw := s.rawEventFromDataFrame(df)
	logPersonalDataFrame(raw, df.Data)
	emit(raw)
	resp := payload.NewSuccessDataFrameResponse()
	resp.SetHeader(payload.DataFrameHeaderKMessageId, df.GetMessageId())
	resp.SetHeader(payload.DataFrameHeaderKContentType, payload.DataFrameContentTypeKJson)
	_ = resp.SetJson(event.NewEventProcessResultSuccess())
	if err := conn.WriteJSON(resp); err != nil {
		return retryPersonal(fmt.Errorf("personal source: write ack: %w", err))
	}
	s.machine.OnEvent()
	return nil
}

