	}

	// Distinguish the exit cause for the contract's `exited` line:
	//   duration deadline    → timeout
	//   parentCtx cancelled  → signal (SIGTERM/SIGINT)
	//   runCtx-only cancelled → signal (stdin EOF)
	parentCtx := ctx

	// --duration: layer a deadline on top of caller-provided ctx. Run
	// returns nil on deadline (clean exit) rather than surfacing the
	// context.DeadlineExceeded as an error to the user.
	var timeoutCtx context.Context
	if cfg.Duration > 0 {
		var cancel context.CancelFunc
		timeoutCtx, cancel = context.WithTimeout(ctx, cfg.Duration)
		defer cancel()
		ctx = timeoutCtx
	}

	// runCtx lets the stdin watcher and the read loop share one cancel
	// without disturbing the timeout/parent contexts (so we can still tell
	// stdin-EOF from a real signal from a duration deadline).
	runCtx, cancelRun := context.WithCancel(ctx)
	defer cancelRun()
	ctx = runCtx

	pipeline, err := BuildPipeline(
		cfg.Format,
		cfg.OutputDir,
		cfg.Routes,
		cfg.Stdout,
		WithProjector(cfg.Projector),
		WithProjectionWarnings(cfg.Stderr),
	)
	if err != nil {
		return fmt.Errorf("consume: build pipeline: %w", err)
	}
	defer pipeline.Close()

	conn, err := discoverBus(busctl.DiscoverConfig{
		WorkDir:        cfg.WorkDir,
		IPCEndpoint:    cfg.IPCEndpoint,
		ClientID:       cfg.ClientID,
		SpawnExtraArgs: cfg.SpawnExtraArgs,
	})
	if err != nil {
		return fmt.Errorf("consume: discover bus: %w", err)
	}
	defer conn.Close()

	// Ensure the conn closes when ctx cancels so blocked Read returns.
	closeOnContext(ctx, conn)

	w := transport.NewWriter(conn)
	r := transport.NewReader(conn)

	hello := transport.Hello{
		Type:        transport.FrameTypeHello,
		ConsumerPID: os.Getpid(),
		EventTypes:  cfg.EventTypes,
		Filter:      cfg.Filter,
		SubscribeID: cfg.SubscribeID,
		Compact:     cfg.Compact,
	}
	if cfg.RuntimeToken != "" {
		hello.CredentialMode = transport.CredentialModeRuntimeToken
	}
	if err := w.WriteJSON(hello); err != nil {
		return fmt.Errorf("consume: write hello: %w", err)
	}

	var ack transport.HelloAck
	if err := r.ReadJSON(&ack); err != nil {
		return fmt.Errorf("consume: read hello_ack: %w", err)
	}
	if ack.Type != transport.FrameTypeHelloAck {
		return fmt.Errorf("consume: unexpected first frame type %q", ack.Type)
	}
	if err := negotiateRuntimeToken(w, r, ack, cfg.RuntimeToken); err != nil {
		return err
	}
	if !cfg.Quiet {
		// Contract: a fixed ready line on stderr BEFORE any stdout event.
		// Parents block on stderr until this appears, then read stdout.
		if cfg.EventKey != "" {
			fmt.Fprintf(cfg.Stderr, "[event] ready event_key=%s bus_pid=%d", cfg.EventKey, ack.BusPID)
			if cfg.ReadySubscribeID != "" {
				fmt.Fprintf(cfg.Stderr, " subscribe_id=%s", cfg.ReadySubscribeID)
			}
			fmt.Fprintln(cfg.Stderr)
		} else {
			fmt.Fprintf(cfg.Stderr, "[event] ready bus_pid=%d\n", ack.BusPID)
		}
		// Secondary diagnostic line (source/state/idle); not part of the
		// ready contract.
		fmt.Fprintf(cfg.Stderr, "[event] bus source=%s state=%s idle_timeout=%ds\n",
			ack.StateSource, ack.SourceState, ack.IdleTimeoutSecs)
		writeTransportState(cfg.Stderr, ack.SourceState, ack.StateSource, ack.SourceObserved, 0)
	}

	// Watch stdin for EOF → graceful shutdown (AI-subprocess contract).
	// The cobra layer only sets Stdin when the watcher should arm (a
	// pipe-style, unbounded run); tests inject it directly.
	if cfg.Stdin != nil {
		go watchStdinEOF(runCtx, cfg.Stdin, cfg.Stderr, cancelRun)
	}

	// Exit-reason contract: on a graceful exit emit a final stderr line
	//   [event] exited — received N event(s) in Xs (reason: <r>)
	// Error returns leave reason empty → no `exited` line (an `Error:` line
	// is printed by the cobra layer instead).
	received := 0
	start := time.Now()
	reason := ""
	defer func() {
		if !cfg.Quiet && reason != "" {
			fmt.Fprintf(cfg.Stderr, "[event] exited — received %d event(s) in %s (reason: %s)\n",
				received, time.Since(start).Round(time.Millisecond), reason)
		}
	}()

	// classifyCancel maps a context-cancelled exit to a contract reason.
	classifyCancel := func() string {
		if timeoutCtx != nil && errors.Is(timeoutCtx.Err(), context.DeadlineExceeded) && parentCtx.Err() == nil {
			return "timeout"
		}
		return "signal"
	}

	for {
		raw, err := r.Read()
		if err != nil {
			if errors.Is(err, io.EOF) {
				reason = "bus_shutdown" // peer closed cleanly
				return nil
			}
			if isCtxCancelled(ctx) {
				reason = classifyCancel()
				return nil
			}
			return fmt.Errorf("consume: read frame: %w", err)
		}
		typ, err := transport.PeekType(raw)
		if err != nil {
			// Malformed frame; skip and continue.
			continue
		}
		switch typ {
		case transport.FrameTypeEvent:
			var ev transport.Event
			if err := json.Unmarshal(raw, &ev); err != nil {
				continue
			}
			if err := pipeline.Deliver(ev); err != nil {
				if errors.Is(err, ErrPipeClosed) {
					// Downstream stdout consumer closed; exit cleanly.
					_ = w.WriteJSON(transport.Bye{
						Type:   transport.FrameTypeBye,
						Reason: "client_done",
					})
					reason = "signal"
					return nil
				}
				return fmt.Errorf("consume: deliver event: %w", err)
			}
			received++
			if cfg.MaxEvents > 0 && received >= cfg.MaxEvents {
				_ = w.WriteJSON(transport.Bye{
					Type:   transport.FrameTypeBye,
					Reason: "client_done",
				})
				reason = "limit"
				return nil
			}
		case transport.FrameTypeBye:
			var bye transport.Bye
			_ = json.Unmarshal(raw, &bye)
			if bye.Reason == transport.ByeReasonRuntimeTokenRejected {
				return fmt.Errorf("consume: %w", runtimecred.ErrRuntimeTokenRejected)
			}
			if !cfg.Quiet {
				fmt.Fprintf(cfg.Stderr, "[event] bus closing: %s\n", bye.Reason)
			}
			reason = "bus_shutdown"
			return nil
		case transport.FrameTypeSourceState:
			if !cfg.Quiet {
				var s transport.SourceState
				_ = json.Unmarshal(raw, &s)
				fmt.Fprintf(cfg.Stderr, "source state: %s (source=%s, attempt=%d)\n", s.State, s.StateSource, s.Attempt)
				writeTransportState(cfg.Stderr, s.State, s.StateSource, s.Observed, s.Attempt)
			}
		case transport.FrameTypeHeartbeat:
			// silent
		default:
			// future frame types: ignored for forward compat
		}
	}
}

func (d *daemon) handleConnection(ctx context.Context, conn net.Conn) {
	conn = ensureCloseOnce(conn)
	defer func() {
		d.conns.Delete(conn)
		_ = conn.Close()
	}()

	r := transport.NewReader(conn)
	w := transport.NewWriter(conn)

	// Expect Hello first.
	var hello transport.Hello
	if err := r.ReadJSON(&hello); err != nil {
		d.log.Warn("bus: hello read failed", "err", err)
		return
	}
	if hello.Type != transport.FrameTypeHello {
		d.log.Warn("bus: first frame not hello", "type", hello.Type)
		return
	}

	// Ad-hoc tooling (status/list/stop) — short-lived RPC, no Hub register.
	if hello.Role == transport.HelloRoleStatus {
		d.handleStatusRPC(w, r)
		return
	}
	if hello.Role == transport.HelloRoleStop {
		// Signal shutdown by cancelling our parent ctx via shutdown().
		// For now, return after acking — daemon.shutdown is wired through
		// daemon's exit path (the busctl/stop command sends SIGTERM in
		// addition to this RPC for v1).
		_ = w.WriteJSON(transport.Bye{Type: transport.FrameTypeBye, Reason: "stop_request"})
		go d.triggerShutdown("stop_request")
		return
	}
	if hello.Role == transport.HelloRoleConsumerStop {
		d.handleConsumerStopRPC(w, r)
		return
	}

	// HelloAck — credentials_source fields are filled in by the daemon
	// runner (which knows from the strict resolver) and exposed via the
	// adapter for forward-compat. v1 leaves them empty here; daemon.Run
	// passes them through future config if the caller wishes.
	ack := d.helloAck()
	handoffLocked := false
	runtimeGeneration := uint64(0)
	defer func() {
		if handoffLocked {
			d.credentialHandoffMu.Unlock()
		}
	}()

	// Runtime credentials use a two-phase additive handshake. The first ack
	// proves capability before the client sends any secret. Only a successful
	// CAS and credential ack permit Hub registration.
	if hello.CredentialMode != "" {
		if hello.CredentialMode != transport.CredentialModeRuntimeToken || d.cfg.CredentialBroker == nil {
			ack.Capabilities = nil
			ack.CredentialGeneration = 0
			if err := w.WriteJSON(ack); err != nil {
				d.log.Warn("bus: incompatible helloack write failed", "err", err)
			}
			return
		}
		d.credentialHandoffMu.Lock()
		handoffLocked = true
		// Terminal state may have been published while this Hello waited for a
		// concurrent credential handoff. Rebuild the ack while holding the gate.
		ack = d.helloAck()
		if err := w.WriteJSON(ack); err != nil {
			d.log.Warn("bus: runtime helloack write failed", "err", err)
			return
		}
		if ack.TerminalReason == transport.ByeReasonRuntimeTokenRejected {
			return
		}

		var update transport.CredentialUpdate
		_ = conn.SetReadDeadline(time.Now().Add(daemonCredentialHandshakeTimeout))
		if err := r.ReadJSON(&update); err != nil {
			// Do not include the decoder error: malformed JSON may contain
			// fragments of the credential.
			d.log.Warn("bus: malformed runtime credential update")
			return
		}
		_ = conn.SetReadDeadline(time.Time{})
		if update.Type != transport.FrameTypeCredentialUpdate {
			_ = w.WriteJSON(transport.CredentialUpdateAck{
				Type:                 transport.FrameTypeCredentialUpdateAck,
				Accepted:             false,
				CredentialGeneration: d.cfg.CredentialBroker.Generation(),
				ErrorCode:            transport.CredentialErrorInvalid,
				Error:                "unexpected credential update frame",
			})
			return
		}
		// Validate registration before applying the credential or sending an
		// accepted ack. Hub.Register performs the same deterministic compile
		// before mutating the Hub; this preflight keeps invalid filters from
		// producing a ready marker after credential negotiation.
		if _, err := compileMatcher(hello.EventTypes, hello.Filter, hello.SubscribeID); err != nil {
			update.Token = ""
			_ = w.WriteJSON(transport.CredentialUpdateAck{
				Type:                 transport.FrameTypeCredentialUpdateAck,
				Accepted:             false,
				CredentialGeneration: d.cfg.CredentialBroker.Generation(),
				ErrorCode:            transport.CredentialErrorRegistration,
				Error:                "consumer registration validation failed",
			})
			d.log.Warn("bus: runtime consumer registration validation failed")
			return
		}

		generation, updateErr := d.cfg.CredentialBroker.Update(update.ExpectedGeneration, update.Token)
		runtimeGeneration = generation
		update.Token = ""
		credentialAck := transport.CredentialUpdateAck{
			Type:                 transport.FrameTypeCredentialUpdateAck,
			Accepted:             updateErr == nil,
			CredentialGeneration: generation,
		}
		if updateErr != nil {
			credentialAck.ErrorCode, credentialAck.Error = classifyCredentialUpdateError(updateErr)
		}
		if err := w.WriteJSON(credentialAck); err != nil {
			d.log.Warn("bus: credential update ack write failed", "err", err)
			return
		}
		if updateErr != nil {
			d.log.Warn("bus: runtime credential update rejected", "error_code", credentialAck.ErrorCode)
			return
		}
	}

	// Regular consumer registration. Local clients retain the original
	// register-before-HelloAck ordering; runtime clients were already acked by
	// the additive handshake above.
	c, err := d.hub.Register(hello)
	if err != nil {
		d.log.Warn("bus: register failed", "err", err, "pid", hello.ConsumerPID)
		_ = w.WriteJSON(transport.Bye{Type: transport.FrameTypeBye, Reason: "register_failed: " + err.Error()})
		return
	}
	if handoffLocked {
		// The runtime broker deliberately keeps the seed pending until the
		// initiating consumer is registered. This prevents ticket acquisition
		// (and an immediate 401) from racing ahead of the only connection that
		// can observe the typed terminal reason.
		if _, activateErr := d.cfg.CredentialBroker.Activate(runtimeGeneration); activateErr != nil {
			d.log.Error("bus: runtime credential activation failed")
			_ = w.WriteJSON(transport.Bye{Type: transport.FrameTypeBye, Reason: "runtime_credential_activation_failed"})
			d.hub.Unregister(c.ID)
			return
		}
	}
	// A local/legacy consumer can arrive after terminal publication but after
	// StopAll took its snapshot. Refuse it synchronously so it cannot observe a
	// clean EOF for a runtime-token rejection.
	if terminalReason := d.getTerminalReason(); terminalReason != "" {
		_ = w.WriteJSON(transport.Bye{Type: transport.FrameTypeBye, Reason: terminalReason})
		d.hub.Unregister(c.ID)
		return
	}
	if handoffLocked {
		d.credentialHandoffMu.Unlock()
		handoffLocked = false
	}
	if hello.CredentialMode == "" {
		if err := w.WriteJSON(ack); err != nil {
			d.log.Warn("bus: helloack write failed", "err", err)
			d.hub.Unregister(c.ID)
			return
		}
	}

	// Writer goroutine pulls from SendCh and writes to the wire.
	writerDone := make(chan struct{})
	go func() {
		defer close(writerDone)
		ticker := time.NewTicker(250 * time.Millisecond)
		defer ticker.Stop()
		last := transport.SourceState{Type: transport.FrameTypeSourceState, State: ack.SourceState, StateSource: ack.StateSource, Observed: ack.SourceObserved}
		for {
			// Give an already-queued targeted stop priority over buffered
			// events. The second select still handles a stop that arrives
			// between this check and the blocking wait.
			select {
			case reason := <-c.StopCh:
				_ = w.WriteJSON(transport.Bye{Type: transport.FrameTypeBye, Reason: reason})
				_ = conn.Close()
				return
			default:
			}
			select {
			case <-ticker.C:
				s := d.sourceStatus()
				next := transport.SourceState{Type: transport.FrameTypeSourceState, State: s.State, StateSource: s.Source, Observed: s.Observed, Attempt: s.ReconnectCount}
				if next != last {
					if err := w.WriteJSON(next); err != nil {
						_ = conn.Close()
						return
					}
					last = next
				}
			case frame, ok := <-c.SendCh:
				if !ok {
					return
				}
				// A stop may have arrived while both channels were ready and the
				// scheduler selected the buffered event. Re-check before starting a
				// potentially blocking event write so terminal reasons stay prompt.
				select {
				case reason := <-c.StopCh:
					_ = w.WriteJSON(transport.Bye{Type: transport.FrameTypeBye, Reason: reason})
					_ = conn.Close()
					return
				default:
				}
				if err := w.WriteJSON(frame); err != nil {
					return
				}
			case reason := <-c.StopCh:
				_ = w.WriteJSON(transport.Bye{Type: transport.FrameTypeBye, Reason: reason})
				_ = conn.Close()
				return
			}
		}
	}()

	// Reader loop: wait for Bye or EOF. Both trigger Unregister.
	for {
		raw, err := r.Read()
		if err != nil {
			if !errors.Is(err, io.EOF) {
				d.log.Debug("bus: consumer read error", "pid", c.PID, "err", err)
			}
			break
		}
		typ, err := transport.PeekType(raw)
		if err != nil {
			continue
		}
		if typ == transport.FrameTypeBye {
			break
		}
		// Heartbeat / future client→bus frames: ignored for v1.
	}
	// Order matters: Unregister first (closes SendCh), then wait for the
	// writer goroutine to drain. The reverse order would deadlock because
	// the writer loops on `range SendCh` until close, but only the Hub
	// can close that channel via Unregister.
	d.hub.Unregister(c.ID)
	<-writerDone
	_ = ctx // for future use (writer ctx-cancel propagation)
}

func (s *PersonalSource) fetchTicket(ctx context.Context) (*ticketResponse, error) {
	accessToken, err := resolveSourceAccessToken(ctx, s.cfg.AccessTokenProvider, s.cfg.AccessToken, "personal source")
	if err != nil {
		// Transient provider failures (network, 429, 5xx) must not kill a
		// long-running source; the reconnect loop retries after backoff.
		if authpkg.ClassifyRefreshFailure(err) == authpkg.RefreshFailureTransient {
			return nil, retryPersonal(err)
		}
		return nil, err
	}
	ticket, status, err := s.fetchTicketAttempt(ctx, accessToken)
	if status == http.StatusUnauthorized && s.cfg.ForceRefreshToken != nil {
		refreshed, refreshErr := refreshRejectedSourceToken(ctx, s.cfg.ForceRefreshToken, accessToken, "personal source", err)
		if refreshErr != nil {
			if authpkg.ClassifyRefreshFailure(refreshErr) == authpkg.RefreshFailureTransient {
				return nil, retryPersonal(refreshErr)
			}
			return nil, refreshErr
		}
		// Retry once with the freshly rotated token; a second 401 stays fatal.
		var retryStatus int
		var retryErr error
		ticket, retryStatus, retryErr = s.fetchTicketAttempt(ctx, refreshed)
		if retryStatus == http.StatusUnauthorized && s.cfg.ClassifyRetryReject != nil {
			superseded, classifyErr := s.cfg.ClassifyRetryReject(refreshed)
			if classifyErr != nil {
				return nil, classifyErr
			}
			if superseded {
				return nil, retryPersonal(retryErr)
			}
		}
		err = retryErr
	}
	return ticket, err
}

