				return fmt.Errorf("invalid --type %q, supported: INTERNAL, EXTERNAL, NORMAL", groupType)
			}

			memberUserIds := parseCSVValues(mustGetFlag(cmd, "users"))

			// 钉钉要求：群主(owner)必须是 useridlist 的成员之一。当前登录用户作为群主，须加入成员列表。
