				"openMessageId":      flagOrFallback(cmd, "message-id", "msg-id"),
				"content":            content,
			}
			if atAll {
				toolArgs["atAll"] = true
			}
			if len(atOpenIDs) > 0 {
				toolArgs["atOpenDingTalkIds"] = atOpenIDs
			}
			return callMCPToolOnServer("im", "edit_message", toolArgs)
		},
