func (p *OAuthProvider) refreshWithRefreshToken(ctx context.Context, data *TokenData) (*TokenData, error) {
	// Use stored Source to determine refresh path (not current runtime state)
	// This ensures refresh works even if environment variables changed since login
	if data.Source == "mcp" {
		p.useTokenLoginRegion(data)
		return p.refreshViaMCP(ctx, data)
	}
	p.useTokenLoginRegion(data)

	// Direct mode: use stored clientId and load saved clientSecret
	clientID := data.ClientID
	if clientID == "" {
		// Fallback for legacy tokens without stored clientId
		clientID = ClientID()
	}
	clientSecret, secretErr := LoadClientSecretStrict(clientID)
	if secretErr != nil {
		return nil, fmt.Errorf("无法刷新 token: Client Secret 存储冲突或不可读，请重新登录: %w", secretErr)
	}
	if clientSecret == "" {
		pair, pairErr := resolveAppCredentialPairWithoutMigration(p.configDir, "", "")
		if pairErr == nil && (clientID == "" || pair.ClientID == clientID) {
			clientID = pair.ClientID
			clientSecret = pair.ClientSecret
		}
	}
	if clientSecret != "" {
		// Complete an app.json-aware historical-slot migration when this token's
		// client ID is also the active custom application. Never replace the
		// credential already selected for this token with stale app.json data.
		if pair, pairErr := resolveAppConfigCredentialPair(p.configDir, false); pairErr == nil &&
			pair.ClientID == clientID && pair.ClientSecret == clientSecret {
			_, _ = ResolveAppConfigCredentialPair(p.configDir)
		}
	}

	if clientID == "" || clientSecret == "" || strings.HasPrefix(clientSecret, "<") {
		return nil, fmt.Errorf("无法刷新 token: 缺少 clientId 或 clientSecret，请重新登录")
	}

	body := map[string]string{
		"clientId":     clientID,
		"clientSecret": clientSecret,
		"refreshToken": data.RefreshToken,
		"grantType":    "refresh_token",
	}
	resp, err := p.postJSON(ctx, UserAccessTokenURLForLoginRegion(p.loginRegion()), body)
	if err != nil {
		return nil, err
	}
	updated, err := p.parseTokenResponse(resp)
	if err != nil {
		return nil, err
	}
	// Preserve original credentials info
	updated.ClientID = data.ClientID
	updated.Source = data.Source
	updated.LoginRegion = data.LoginRegion
	updated.PersistentCode = data.PersistentCode
	updated.CorpID = data.CorpID
	updated.UserID = data.UserID
	updated.UserName = data.UserName
	updated.RepairOrganizationMirror = data.RepairOrganizationMirror
	if updated.CorpName == "" {
		updated.CorpName = data.CorpName
	}

	// Refresh runs under lockedRefresh's dual-layer lock; use the lock-free
	// saver to avoid re-acquiring the non-reentrant lock (deadlock).
	if err := oauthSaveTokenLocked(p.configDir, updated); err != nil {
		return nil, fmt.Errorf("保存刷新后的 token 失败（旧 refresh_token 已失效，请重新登录）: %w", err)
	}
	return updated, nil
}

func (p *OAuthProvider) forceRefreshRejectedTokenOnce(
	ctx context.Context,
	profile string,
	rejectedAccessToken string,
	key rejectedTokenRefreshKey,
) (string, error, bool) {
	lock, err := oauthAcquireLock(ctx, p.configDir)
	if err != nil {
		return "", fmt.Errorf("acquiring dual lock: %w", err), false
	}
	defer lock.Release()

	data, err := loadOAuthTokenUnderHeldLock(p.configDir, profile)
	if err != nil {
		return "", fmt.Errorf("reload rejected token: %w", err), false
	}
	current := strings.TrimSpace(data.AccessToken)
	if current == "" {
		clearRejectedTokenRefreshFailure(key)
		return "", fmt.Errorf("stored access token is empty"), false
	}
	if current != rejectedAccessToken {
		clearRejectedTokenRefreshFailure(key)
		return current, nil, false
	}
	if cachedErr := recentRejectedTokenRefreshFailure(key); cachedErr != nil {
		return "", cachedErr, false
	}
	if !data.IsRefreshTokenValid() {
		return "", fmt.Errorf("refresh_token 已过期"), true
	}
	if err := preflightTokenRefreshPersistence(p.configDir, data); err != nil {
		return "", fmt.Errorf("本地登录态无法安全更新: %w", err), true
	}

	refreshed, err := oauthRefreshToken(p, ctx, data)
	if err != nil {
		return "", err, true
	}
	if refreshed == nil || strings.TrimSpace(refreshed.AccessToken) == "" {
		return "", fmt.Errorf("force refresh returned empty access token"), true
	}
	return strings.TrimSpace(refreshed.AccessToken), nil, false
}

func (t *TokenData) IsAccessTokenValid() bool {
	if t == nil || t.AccessToken == "" {
		return false
	}
	// Give 5-minute buffer before actual expiry.
	return time.Now().Before(t.ExpiresAt.Add(-5 * time.Minute))
}

func newAuthLoginCommand(patCaller edition.ToolCaller) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "login",
		Short: "登录钉钉（自动刷新 token，必要时扫码）",
		Long: `登录钉钉并获取认证凭证。

支持的登录方式:
  - OAuth Loopback 流 (默认): 本机自动起 127.0.0.1 监听接收回调，浏览器授权后自动完成
  - OAuth 设备流 (--device): 显示 user_code + 短 URL，适合 SSH 远程 / 容器 / 无头环境
  - 自有应用 OAuth (--client-id/--client-secret): 使用指定应用完成用户授权
  - 直接提供 Token (--token): 跳过授权，使用已有 token

不支持的登录方式:
  - 邮箱/密码登录
  - 手机号/验证码登录
  - 无用户授权的纯应用凭证 (client_credentials) 登录

区域:
  - 默认使用国内钉钉 .com 登录与服务端点
  - --intl（或 --international）使用国际版 .io 登录；后续业务命令按所选 profile 自动路由
  - --intl 登录默认输出英文文案与英文授权页；需要中文时显式设置 DWS_LANG=zh

注意: SSH 远程或无头环境（无本地浏览器可访问远端的 127.0.0.1）请使用 --device，
      否则 OAuth 回调会跳到本机不可达的 127.0.0.1 链接，授权完成后无法回写 token。
      自有应用的 Client ID/Client Secret 必须完整成对，且仅在授权成功后持久化到 app config/Keychain。

示例:
  dws auth login              # 本机登录并新增/刷新一个组织 profile
  dws auth login --profile <corpId>  # 指定本次授权目标组织，不持久切换当前组织
  dws auth login --intl       # 使用钉钉国际版 .io 登录入口
  dws auth login --intl --pre-url https://pre-login.dingtalk.io
  dws auth login --intl --pre-url https://pre-mcp.dingtalk.io
  dws auth login --recommend  # 无交互批量授权服务端推荐权限
  dws auth login --device     # SSH 远程 / 无头环境登录 (设备流)
  dws auth login --force      # 兼容保留；login 默认已忽略缓存并进入授权流程
  dws auth login --token xxx  # 使用指定 token`,
		DisableAutoGenTag: true,
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := resolveAuthLoginConfig(cmd)
			if err != nil {
				return err
			}
			restoreLang := authLoginPushDisplayLang(cfg)
			defer restoreLang()
			var preOverrides authLoginEndpointOverrides
			if cfg.PreURL != "" {
				var err error
				preOverrides, err = authLoginEndpointOverridesForPreURL(cfg.PreURL)
				if err != nil {
					return err
				}
				restoreLoginBaseURL := authpkg.PushLoginBaseURLOverride(preOverrides.LoginURL)
				defer restoreLoginBaseURL()
			}
			mcpBaseURL, mcpPersistence, err := authLoginMCPBaseURLForConfig(cfg, preOverrides)
			if err != nil {
				return err
			}
			restoreMCPBaseURL := authpkg.PushMCPBaseURLOverride(mcpBaseURL)
			defer restoreMCPBaseURL()
			configDir := defaultConfigDir()
			var tokenData *authpkg.TokenData
			format, _ := cmd.Root().PersistentFlags().GetString("format")
			postLoginTUIMode := !cfg.Yes && authLoginShouldUsePostLoginTUIMode(cmd, format, cfg.Recommend)
			recommendAuthMode := cfg.Recommend || postLoginTUIMode
			humanAuthMode := !cfg.Yes && authLoginShouldUseHumanAuthorizationMode(cmd, format, recommendAuthMode)

			switch {
			case strings.TrimSpace(cfg.Token) != "":
				tokenData = &authpkg.TokenData{
					AccessToken: cfg.Token,
					ExpiresAt:   time.Now().Add(config.ManualTokenExpiry),
				}
				if cfg.International {
					tokenData.LoginRegion = string(authpkg.LoginRegionInternational)
				}
				if err := authSaveTokenData(configDir, tokenData); err != nil {
					return apperrors.NewInternal(fmt.Sprintf("failed to persist auth token: %v", err))
				}
			case cfg.Device:
				loginCtx, cancel := context.WithTimeout(cmd.Context(), config.DeviceFlowTimeout)
				defer cancel()

				provider := authpkg.NewDeviceFlowProvider(configDir, nil)
				provider.Output = cmd.ErrOrStderr()
				provider.NoBrowser, _ = cmd.Flags().GetBool("no-browser")
				if cfg.International {
					provider.SetLoginRegion(authpkg.LoginRegionInternational)
				}
				provider.IdentityEnricher = func(ctx context.Context, data *authpkg.TokenData) error {
					return enrichAuthLoginProfileFromContact(ctx, configDir, patCaller, data, authLoginHistoryHint{
						Selector: cfg.HistoryProfileSelector,
						Explicit: cfg.HistoryProfileSelectorExplicit,
					})
				}
				tokenData, err = authDeviceLogin(provider, loginCtx)
				if err != nil {
					return authLoginFlowError("device authorization failed", err)
				}
			default:
				loginCtx, cancel := context.WithTimeout(cmd.Context(), config.OAuthFlowTimeout)
				defer cancel()

				provider := authpkg.NewOAuthProvider(configDir, nil)
				provider.Output = cmd.ErrOrStderr()
				provider.NoBrowser, _ = cmd.Flags().GetBool("no-browser")
				provider.TargetCorpID = cfg.TargetCorpID
				if cfg.International {
					provider.LoginRegion = authpkg.LoginRegionInternational
				}
				provider.IdentityEnricher = func(ctx context.Context, data *authpkg.TokenData) error {
					return enrichAuthLoginProfileFromContact(ctx, configDir, patCaller, data, authLoginHistoryHint{
						Selector: cfg.HistoryProfileSelector,
						Explicit: cfg.HistoryProfileSelectorExplicit,
					})
				}
				configureOAuthProviderCompatibility(provider, configDir)
				tokenData, err = authOAuthLogin(provider, loginCtx, authLoginForcesAuthorization(cfg))
				if err != nil {
					return authLoginFlowError("dingtalk login failed", err)
				}
			}

			if tokenData != nil {
				if err := persistAuthLoginMCPBaseURL(configDir, mcpBaseURL, mcpPersistence); err != nil {
